CREATE TABLE public.tournament_terminal_settlements("tournament_id" uuid NOT NULL,"winner_id" uuid NOT NULL,"settlement_mode" text NOT NULL,"started_status" text NOT NULL,"prize_pool" numeric(15,2) NOT NULL,"bounty_pool" numeric(15,2) NOT NULL,"cash_payout_count" integer NOT NULL,"cash_payout_total" numeric(15,2) NOT NULL,"bounty_payout_total" numeric(15,2) NOT NULL,"mystery_was_active" boolean NOT NULL,"mystery_pool_cents" bigint NOT NULL,"cash_receipt" jsonb NOT NULL,"mystery_receipt" jsonb NOT NULL,"bounty_receipt" jsonb NOT NULL,"closed_table_count" integer NOT NULL,"closed_table_ids" uuid[] NOT NULL,"source_seat_count" integer NOT NULL,"source_seat_ids" uuid[] NOT NULL,"released_seat_count" integer NOT NULL,"released_seat_ids" uuid[] NOT NULL,"rake_amount" numeric(15,2) NOT NULL,"rake_destination" text NOT NULL,"rake_settled_at" timestamp with time zone NOT NULL,"rake_attributed_at" timestamp with time zone NOT NULL,"rake_attributed_users" integer NOT NULL,"escrow_closed_at" timestamp with time zone NOT NULL,"escrow_close_note" text NOT NULL,"completed_at" timestamp with time zone NOT NULL,"settled_at" timestamp with time zone NOT NULL DEFAULT transaction_timestamp(),"receipt_version" integer NOT NULL DEFAULT 1);
ALTER TABLE public.tournament_terminal_settlements ADD CONSTRAINT "tournament_terminal_settlements_bounty_payout_total_check" CHECK (((bounty_payout_total >= (0)::numeric) AND (bounty_payout_total = round(bounty_payout_total, 2))));
ALTER TABLE public.tournament_terminal_settlements ADD CONSTRAINT "tournament_terminal_settlements_bounty_pool_check" CHECK (((bounty_pool >= (0)::numeric) AND (bounty_pool = round(bounty_pool, 2))));
ALTER TABLE public.tournament_terminal_settlements ADD CONSTRAINT "tournament_terminal_settlements_bounty_receipt_check" CHECK ((jsonb_typeof(bounty_receipt) = 'object'::text));
ALTER TABLE public.tournament_terminal_settlements ADD CONSTRAINT "tournament_terminal_settlements_cash_payout_count_check" CHECK ((cash_payout_count >= 0));
ALTER TABLE public.tournament_terminal_settlements ADD CONSTRAINT "tournament_terminal_settlements_cash_payout_total_check" CHECK (((cash_payout_total >= (0)::numeric) AND (cash_payout_total = round(cash_payout_total, 2))));
ALTER TABLE public.tournament_terminal_settlements ADD CONSTRAINT "tournament_terminal_settlements_cash_receipt_check" CHECK ((jsonb_typeof(cash_receipt) = 'object'::text));
ALTER TABLE public.tournament_terminal_settlements ADD CONSTRAINT "tournament_terminal_settlements_check" CHECK ((cash_payout_total = prize_pool));
ALTER TABLE public.tournament_terminal_settlements ADD CONSTRAINT "tournament_terminal_settlements_check1" CHECK ((bounty_payout_total = bounty_pool));
ALTER TABLE public.tournament_terminal_settlements ADD CONSTRAINT "tournament_terminal_settlements_check2" CHECK (((mystery_was_active AND (mystery_pool_cents > 0)) OR ((NOT mystery_was_active) AND (mystery_pool_cents = 0))));
ALTER TABLE public.tournament_terminal_settlements ADD CONSTRAINT "tournament_terminal_settlements_check3" CHECK ((closed_table_count = cardinality(closed_table_ids)));
ALTER TABLE public.tournament_terminal_settlements ADD CONSTRAINT "tournament_terminal_settlements_check4" CHECK ((source_seat_count = cardinality(source_seat_ids)));
ALTER TABLE public.tournament_terminal_settlements ADD CONSTRAINT "tournament_terminal_settlements_check5" CHECK ((released_seat_count = cardinality(released_seat_ids)));
ALTER TABLE public.tournament_terminal_settlements ADD CONSTRAINT "tournament_terminal_settlements_check6" CHECK ((released_seat_ids <@ source_seat_ids));
ALTER TABLE public.tournament_terminal_settlements ADD CONSTRAINT "tournament_terminal_settlements_check7" CHECK (((rake_settled_at <= settled_at) AND (rake_attributed_at <= settled_at)));
ALTER TABLE public.tournament_terminal_settlements ADD CONSTRAINT "tournament_terminal_settlements_check8" CHECK ((escrow_closed_at <= settled_at));
ALTER TABLE public.tournament_terminal_settlements ADD CONSTRAINT "tournament_terminal_settlements_check9" CHECK ((completed_at <= settled_at));
ALTER TABLE public.tournament_terminal_settlements ADD CONSTRAINT "tournament_terminal_settlements_closed_table_count_check" CHECK ((closed_table_count >= 0));
ALTER TABLE public.tournament_terminal_settlements ADD CONSTRAINT "tournament_terminal_settlements_closed_table_ids_check" CHECK ((array_position(closed_table_ids, NULL::uuid) IS NULL));
ALTER TABLE public.tournament_terminal_settlements ADD CONSTRAINT "tournament_terminal_settlements_escrow_close_note_check" CHECK ((length(btrim(escrow_close_note)) > 0));
ALTER TABLE public.tournament_terminal_settlements ADD CONSTRAINT "tournament_terminal_settlements_mystery_pool_cents_check" CHECK ((mystery_pool_cents >= 0));
ALTER TABLE public.tournament_terminal_settlements ADD CONSTRAINT "tournament_terminal_settlements_mystery_receipt_check" CHECK ((jsonb_typeof(mystery_receipt) = 'object'::text));
ALTER TABLE public.tournament_terminal_settlements ADD CONSTRAINT "tournament_terminal_settlements_pkey" PRIMARY KEY (tournament_id);
ALTER TABLE public.tournament_terminal_settlements ADD CONSTRAINT "tournament_terminal_settlements_prize_pool_check" CHECK (((prize_pool >= (0)::numeric) AND (prize_pool = round(prize_pool, 2))));
ALTER TABLE public.tournament_terminal_settlements ADD CONSTRAINT "tournament_terminal_settlements_rake_amount_check" CHECK (((rake_amount >= (0)::numeric) AND (rake_amount = round(rake_amount, 2))));
ALTER TABLE public.tournament_terminal_settlements ADD CONSTRAINT "tournament_terminal_settlements_rake_attributed_users_check" CHECK ((rake_attributed_users >= 0));
ALTER TABLE public.tournament_terminal_settlements ADD CONSTRAINT "tournament_terminal_settlements_rake_destination_check" CHECK ((length(btrim(rake_destination)) > 0));
ALTER TABLE public.tournament_terminal_settlements ADD CONSTRAINT "tournament_terminal_settlements_receipt_version_check" CHECK ((receipt_version = 1));
ALTER TABLE public.tournament_terminal_settlements ADD CONSTRAINT "tournament_terminal_settlements_released_seat_count_check" CHECK ((released_seat_count >= 0));
ALTER TABLE public.tournament_terminal_settlements ADD CONSTRAINT "tournament_terminal_settlements_released_seat_ids_check" CHECK ((array_position(released_seat_ids, NULL::uuid) IS NULL));
ALTER TABLE public.tournament_terminal_settlements ADD CONSTRAINT "tournament_terminal_settlements_settlement_mode_check" CHECK ((settlement_mode = ANY (ARRAY['places'::text, 'final_table_deal'::text])));
ALTER TABLE public.tournament_terminal_settlements ADD CONSTRAINT "tournament_terminal_settlements_source_seat_count_check" CHECK ((source_seat_count >= 0));
ALTER TABLE public.tournament_terminal_settlements ADD CONSTRAINT "tournament_terminal_settlements_source_seat_ids_check" CHECK ((array_position(source_seat_ids, NULL::uuid) IS NULL));
ALTER TABLE public.tournament_terminal_settlements ADD CONSTRAINT "tournament_terminal_settlements_started_status_check" CHECK ((started_status = ANY (ARRAY['RUNNING'::text, 'COMPLETING'::text])));
ALTER TABLE public.tournament_terminal_settlements ADD CONSTRAINT "tournament_terminal_settlements_tournament_id_fkey" FOREIGN KEY (tournament_id) REFERENCES tournaments(id) ON DELETE RESTRICT;
